"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";

// The document HTML is generated by the API, carries a script-src 'none' CSP and is shown same-origin so its height can be read.
export function HostedDoc({ html, title }) {
  const flowing = html.includes('<body class="scr flow">');
  const width = flowing ? 820 : 860;
  const box = useRef(null);
  const frame = useRef(null);
  const [scale, setScale] = useState(1);
  const [height, setHeight] = useState(1100);

  useEffect(() => {
    const node = box.current;
    if (!node) return undefined;
    const observer = new ResizeObserver(([entry]) => setScale(Math.min(1, entry.contentRect.width / width)));
    observer.observe(node);
    return () => observer.disconnect();
  }, [width]);

  const measure = () => {
    const doc = frame.current?.contentDocument;
    if (doc?.documentElement) setHeight(doc.documentElement.scrollHeight);
  };

  return (
    <div className={`hp-doc${flowing ? "" : " is-pages"}`} ref={box} style={{ height: height * scale }}>
      <iframe
        ref={frame}
        title={title}
        srcDoc={html}
        sandbox="allow-same-origin"
        onLoad={measure}
        style={{ width, height, transform: `scale(${scale})`, transformOrigin: "0 0" }}
      />
    </div>
  );
}

export function CopyButton({ value, label = "Copy" }) {
  const [done, setDone] = useState(false);
  return (
    <button type="button" onClick={async () => {
      await navigator.clipboard?.writeText(value).catch(() => {});
      setDone(true);
      setTimeout(() => setDone(false), 1500);
    }}>{done ? "Copied" : label}</button>
  );
}

export function PrintButton({ href }) {
  return (
    <a className="btn" href={href} target="_blank" rel="noopener noreferrer">
      <svg className="ic" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2" /><path d="M6 14h12v7H6z" /></svg>
      Print
    </a>
  );
}

export function QuoteDecision({ token }) {
  const router = useRouter();
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  async function decide(decision) {
    setBusy(true);
    setError("");
    const response = await fetch(`/q/${token}/decision`, { method: "POST", body: JSON.stringify({ decision, name }) }).catch(() => null);
    const data = response ? await response.json().catch(() => ({})) : {};
    setBusy(false);
    if (!response?.ok) return setError(data.error || "That did not go through. Please try again.");
    router.refresh();
  }

  return (
    <div>
      <label className="field">Your name<input value={name} onChange={(event) => setName(event.target.value)} maxLength={120} autoComplete="name" /></label>
      <div className="two">
        <button type="button" className="btn primary" disabled={busy || !name.trim()} onClick={() => decide("accept")}>Accept quote</button>
        <button type="button" className="btn" disabled={busy} onClick={() => decide("decline")}>Decline</button>
      </div>
      {error ? <p className="err" role="alert">{error}</p> : null}
    </div>
  );
}
